import json,re,collections
from pathlib import Path

def extract(s):
 s=s[-300:] if len(s)>300 else s
 a=re.findall(r'(\-?[0-9\.\,]+)',s)
 for v in reversed(a):
  if v not in ('','.'): return v

def strict(s):
 a=re.findall(r'#### (\-?[0-9\.\,]+)',s[-300:])
 return a[-1].replace(',','').replace('$','') if a else None
for p in sorted(Path('/workspace/results/run60/val_generations').glob('[0-9]*.jsonl'),key=lambda p:int(p.stem)):
 rows=[json.loads(x) for x in p.read_text().splitlines()]
 mism=[r for r in rows if ((extract(r['output']) or '').replace(',','')==r['gts'].replace(',','')) != bool(r['acc'])]
 hashes=[r['output'] for r in rows if len(r['output'])>2200]
 c=collections.Counter(hashes)
 finalbox=sum(bool(re.search(r'(?:\\boxed|####)',r['output'])) for r in rows)
 print(p.stem, 'n',len(rows),'acc',sum(r['acc'] for r in rows)/len(rows),'char_mean',round(sum(map(lambda r:len(r['output']),rows))/len(rows),1),'long>2200',len(hashes),'boxed_or####',finalbox,'unique_long',len(c),'largest_repeat',c.most_common(1)[0][1] if c else 0,'recomputed_mismatch',len(mism))
 print('  correct counts',collections.Counter(r['acc'] for r in rows))
 for r in rows:
  if r['acc'] and not re.search(r'(?:\\boxed|####)',r['output']):
   print('  CORRECT WITHOUT BOX/#### sample:',repr(r['output'][-700:]),'gt',r['gts']); break
 for r in rows:
  if len(r['output'])>2200:
   print('  LONG sample acc',r['acc'],'len',len(r['output']),'tail',repr(r['output'][-900:])); break
