 print('\nLONGEST:')
 for r in sorted(rows,key=lambda r:len(r['output']),reverse=True)[:2]:
  print('gt',r['gts'],'score',r['score'],'chars',len(r['output']),'tail',repr(r['output'][-1300:]))
