from pathlib import Path
rr=[json.loads(x)['data'] for x in Path('/workspace/results/run60/metrics.jsonl').read_text().splitlines()][1:]
for key in ['training/epoch','actor/pg_loss','actor/pg_clipfrac','actor/grad_norm','actor/perf/max_memory_allocated_gb','response_length/min','response_length/max','response/aborted_ratio','prompt_length/clip_ratio']:
 print(key,[(i+1,r[key]) for i,r in enumerate(rr) if r.get(key)!=rr[0].get(key)][:5] if key=='training/epoch' else {'first':rr[0].get(key),'last':rr[-1].get(key),'min':min(r[key] for r in rr if key in r),'max':max(r[key] for r in rr if key in r)})
if all('actor/pg_loss' in r and 'critic/advantages/mean' in r for r in rr):
 print('pg_loss equals negative advantage mean?',all(math.isclose(r['actor/pg_loss'],-r['critic/advantages/mean'],rel_tol=2e-6,abs_tol=1e-8) for r in rr))
print('Training input/reward identity across selected steps:')
rr2={int(p.stem):[json.loads(x) for x in p.read_text().splitlines()] for p in Path('/workspace/results/run60/rollouts').glob('[0-9]*.jsonl')}
print({s:len({r['input'] for r in x}) for s,x in rr2.items()})
for a,b in itertools.combinations(rr2,2):
 A={r['input'] for r in rr2[a]};B={r['input'] for r in rr2[b]}
 print('overlap',a,b,len(A&B),'identical outputs by input',sum(any(r['output']==t['output'] for t in rr2[b] if t['input']==r['input']) for r in rr2[a]))
print('val order identical',all([[r['input'] for r in [json.loads(x) for x in p.read_text().splitlines()]] for p in []]))
vs={int(p.stem):[json.loads(x) for x in p.read_text().splitlines()] for p in Path('/workspace/results/run60/val_generations').glob('[0-9]*.jsonl')}
print({a:vs[a][0]['input']==vs[0][0]['input'] for a in vs})
print('val rows per unique prompt',{a:len({r['input'] for r in rows}) for a,rows in vs.items()})
