import json,re,collections
from pathlib import Path

def nums(s): return re.findall(r'(\-?[0-9\.\,]+)',s[-300:])
def ext(s):
 for a in reversed(nums(s)):
  if a not in ('','.'): return a
for folder in ['rollouts','val_generations']:
 print('\n',folder)
 for p in sorted((Path('/workspace/results/run60')/folder).glob('[0-9]*.jsonl'),key=lambda p:int(p.stem)):
  rr=[json.loads(x) for x in p.read_text().splitlines()]
  mism=[]
  for r in rr:
   a=ext(r['output'])
   normalized=a.replace(',','') if a else None
   if (normalized==r['gts'])!=bool(r['score']): mism.append((r,a,normalized))
  boxes=[r for r in rr if r['score'] and re.findall(r'\\boxed\s*\{\s*([^{}]+)',r['output']) and ext(re.findall(r'\\boxed\s*\{\s*([^{}]+)',r['output'])[-1]) not in (None,r['gts'])]
  print(p.stem,'normalization mismatches',len(mism),'scored-with-other-final-box',len(boxes))
  for r,a,n in mism[:3]: print(' mismatch extracted',repr(a),'gt',r['gts'],'score',r['score'],'tail',repr(r['output'][-260:]))
  for r in boxes[:1]: print(' box-positive tail',repr(r['output'][-400:]),'gt',r['gts'])
print('\nPaired held-out changes from baseline')
vs={int(p.stem):[json.loads(x) for x in p.read_text().splitlines()] for p in Path('/workspace/results/run60/val_generations').glob('[0-9]*.jsonl')}
for s,rr in sorted(vs.items()):
 gained=sum(not a['score'] and b['score'] for a,b in zip(vs[0],rr));lost=sum(a['score'] and not b['score'] for a,b in zip(vs[0],rr));same=sum(a['output']==b['output'] for a,b in zip(vs[0],rr))
 print(s,'gained',gained,'lost',lost,'net',gained-lost,'identical outputs',same)
